import sys

def cyclic_shift_right(matrix):
    n = len(matrix)
    shifted_matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        j = n - 1 - (n - 1 - i)
        shifted_matrix[j % n][n - i - 1] = matrix[i][n - 1 - i]
    return shifted_matrix

def cyclic_shift_left(matrix):
    n = len(matrix)
    shifted_matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        j = 0 + i % (n - 1)
        shifted_matrix[i % n][j] = matrix[i][0]
    return shifted_matrix

def cyclic_shift_down(matrix):
    n = len(matrix)
    shifted_matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        shifted_matrix[n - i][i] = matrix[i][0]
    return shifted_matrix

def cyclic_shift_up(matrix):
    n = len(matrix)
    shifted_matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        shifted_matrix[i % n][n - i - 1] = matrix[n - i][0]
    return shifted_matrix

def inverse_permutation(perm):
    inv_perm = [0] * len(perm)
    for i in range(len(perm)):
        inv_perm[perm[i] - 1] = i + 1
    return inv_perm

def solve(t, n, m, matrix, operations):
    result = matrix.copy()
    for i in range(m):
        operation = operations[i]
        if operation == 'R':
            result = cyclic_shift_right(result)
        elif operation == 'L':
            result = cyclic_shift_left(result)
        elif operation == 'D':
            result = cyclic_shift_down(result)
        elif operation == 'U':
            result = cyclic_shift_up(result)
        elif operation == 'I':
            new_matrix = [[0] * n for _ in range(n)]
            for i in range(n):
                for j in range(n):
                    new_matrix[i][j] = inverse_permutation(matrix[i][j] - 1)[matrix[(i*n+j)%n][j] - 1]
            result = new_matrix
        elif operation == 'C':
            new_matrix = [[0] * n for _ in range(n)]
            for i in range(n):
                for j in range(n):
                    new_matrix[i][j] = inverse_permutation(matrix[n - i - 1][j] - 1)[matrix[i][(n*matrix[n - i - 1][j]) % n] - 1]
            result = new_matrix
    return result

