    elif op_char == 'U':
        for row in range(n):
            for col in range(1, n):
                if col < n and matrix[row][col] != matrix[n-1][col]:
                    matrix[row][col], matrix[n-1][col] = matrix[n-1][col], matrix[row][col]
    elif op_char == 'R':
        for col in range(n):
            for row in range(1, n):
                if row < n and matrix[row][col] != matrix[row][n-1]:
                    matrix[row][col], matrix[row][n-1] = matrix[row][n-1], matrix[row][col]
    elif op_char == 'L':
        for col in range(n):
            for row in range(1, n):
                if row < n and matrix[row][col] != matrix[n-1][col]:
                    matrix[row][col], matrix[n-1][col] = matrix[n-1][col], matrix[row][col]
    elif op_char == 'C':
        for col in range(n):
