from functools import cache

def power(x, n, mod):
    result = 1
    while n > 0:
        if n % 2 == 1:
            result = (result * x) % mod
        x = (x * x) % mod
        n //= 2
    return result

def mod_inverse(e, m):
    return power(e, m - 2, m)

@cache
def solve(n):
    total = set()
    if n == 0:
        return total

    for i in range(8):
        lower, upper = i, i + 7
        count = power(2, 8, 10**9 + 7)
        for num in range(7 - i, lower, -1):
            count *= (7 - num) % 1000000007
