from collections import defaultdict

def find_minimum_moves(sequence):
    n = len(sequence)
    prefix_sum = [0] * (n + 1)
    for i in range(n):
        prefix_sum[i + 1] = prefix_sum[i] + sequence[i]

    dp = defaultdict(int)
    def count_changes(start):
        if start in dp:
            return dp[start]
        min_changes = float('inf')
        total = sum(sequence) // n
        for end in range(start + 1, n + 1):
            if (prefix_sum[end] - prefix_sum[start] - (end - start - 1) * start >= total) and (end - start - 1 > 0):
                min_changes = min(min_changes, count_changes(end) + 1)
        dp[start] = min_changes
        return min_changes

    return count_changes(0)

