import sys

def can_be_cool(num, length):
    for i in range(length):
        if (num - length + i) > 0:
            if num % (length - i) == 0 and (num // (length - i)) >= i:
                return True
    return False

def min_moves_to_cool_sequence(n, nums):
    # Initialize a dictionary to keep track of existing sums
    existing_sums = {}
    for i, num in enumerate(nums):
        current_sum = 0
        for candidate in range(num + 1):
            current_sum += candidate
            if current_sum in existing_sums:
                continue
            if can_be_cool(current_sum, len(nums) - i - 1):
                existing_sums[current_sum] = True
    # If no cool sum is found, it means all numbers are in a single increasing sequence
    if not existing_sums:
        return 0

    # Sort the existing sums to use the second smallest as the offset
    min_offset = min(existing_sums.keys())
    candidate_sum = nums[-1] - nums[0] + nums[1]
    while not can_be_cool(candidate_sum, len(nums) - 1):
        already_accomplished = set(existing_sums.keys()) - {min_offset}
        start = max(already_accomplished, candidate_sum) - 1
        if start == 0:
            return 0
        if start * 2 - candidate_sum in existing_sums:
            candidate_sum = start * 2
        else:
            candidate_sum += start

    return (len(nums) - 1) - candidate_sum + min_offset

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    nums = list(map(int, data[1:]))
    print(min_moves_to_cool_sequence(n, nums))
