import sys

class Cube:
    def __init__(self, matrix):
        self.matrix = matrix
        self.visited = set()
        self.queue = [(0, 0, 0)]

    def adjacent_height(self, position, direction):
        x, y = position
        dx, dy = direction
        neighbor = None
        for direction in [(dx, dy), (-dx, dy), (dx, -dy), (-dx, -dy)]:
            neighbor_pos = (x + direction[0], y + direction[1])
            if 0 <= neighbor_pos[0] < len(self.matrix) and 0 <= neighbor_pos[1] < len(self.matrix[0]):
                if (neighbor_pos, direction) not in self.visited and self.matrix[neighbor_pos[0]][neighbor_pos[1]] == self.matrix[position[0]][position[1]]:
                    neighbor = neighbor_pos
                    break
        return neighbor

    def bfs(self):
        while self.queue:
            x, y, height = self.queue.pop(0)
            for direction in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                neighbor = self.adjacent_height((x, y), direction)
                if neighbor:
                    if (x + neighbor[0], y + neighbor[1], direction[0] * neighbor[0] + direction[1] * neighbor[1]) not in self.visited:
                        self.visited.add((x + neighbor[0], y + neighbor[1], direction[0] * neighbor[0] + direction[1] * neighbor[1]))
                        self.queue.append((x + neighbor[0], y + neighbor[1], height + direction[0] * neighbor[0] + direction[1] * neighbor[1]))
        for i in range(len(self.visited)):
            y = self.visited[i][1]
            self.matrix[i][y] += self.visited[i][0]
        return self.matrix

