import sys

def min_steps_to_complete_friends(friends_count, friendships):
    # Accept Friend relationship in the form of an undirected graph and get Adjacency list
    graph = [[] for _ in range(friends_count + 1)]
    for a, b in friendships:
        graph[a].append(b)
        graph[b].append(a)

    def min_steps_helper(node, parent, closest):
        steps = set()
        visited = set()
        seconds_completed = set()

        # Add initial node to steps
        steps.add(node)

        def dfs(node):
            if node in closest:
                seconds_completed.add(node)

            visited.add(node)
            for neighbor in graph[node]:
                if neighbor in visited:
                    if neighbor in closest[node]:
                        steps.add(node)
                    else:
                        steps.add(neighbor)
                elif neighbor not in seconds_completed:
                    dfs(neighbor)

            visited.remove(node)

        dfs(node)
        steps.difference_update(visible_friends(node, parent))
        steps.difference_update(seconds_completed)
        return steps

    def visible_friends(node, parent):
        friends = set()
        visited = set()
        for child in graph[node]:
            if child == parent:
                continue

            if child in nodes_adapted:
                friends.update(nodes_adapted[child])
            else:
                visited.add(child)
                friends.update(visible_friends(child, node))
        return friends.difference(visited)

    # To take lowest degree nodes first, we promote the minimum degree node as pivot of other guests in the next step
    sorted_friends = sorted(range(1, friends_count + 1), key=lambda k: len(graph[k]), reverse=True)

    # Initialize nodes required of visible_friends()
    # clear hidden friend restrictions as starting states cover this scenario
    visible_friends_to_guest = {node: set() for node in range(1, friends_count + 1)}

    # Tags low degree nodes as "visible"
    pivot_tag = set()
    for pivot in sorted_friends:
        close = set([filename for filename in graph[pivot] if len(visible_friends_to_guest[filename]) > pivot])

        for other in close:
            nodes_adapted[other].add(pivot)
            visible_friends_to_guest[pivot].add(other)

    pivot_tag.update(pivot for pivot in visible_friends_to_guest.keys() if len(visible_friends_to_guest[pivot]) == pivot)

    ready_steps = set()
    for i in range(friends_count):
        if sorted_friends[i] in pivot_tag:
            continue

        new_steps = set()
        visible_friends(sorted_friends[i], sorted_friends[i]).update(graph[sorted_friends[i]])
        ready_steps.difference_update(visible_friends_to_guest[sorted_friends[i]])

        for other in new_steps:
            usable = len(graph[other]) > len(visible_friends_to_guest[sorted_friends[i]])
            must_visible = usable and graph[sorted_friends[i]] & visible_friends_to_guest[other]
            while must_visible:
                need, resource, search = sorted(list(must_visible), key=lambda x: len(visible_friends_to_guest[x]))
                visible_friends_to_guest[need].update(graph[need])
                new_steps.difference_update(search)
        ready_steps.update(new_steps)

    return len(ready_steps), ready_steps


if __name__ == "__main__":
    n, m = map(int, input().split())
    friendships = [list(map(int, input().split())) for _ in range(m)]
    res, pairs = min_steps_to_complete_friends(n, friendships)
    print(res)
    print(' '.join(map(str, pairs)))
