    return matrix

def rotate_matrix_left(matrix):
    n = len(matrix)
    new_matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            new_matrix[n - j - 1][i] = matrix[i][j]
    return new_matrix

def rotate_matrix_right(matrix):
    n = len(matrix)
    new_matrix = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            new_matrix[j][n - i - 1] = matrix[i][j]
    return new_matrix

def rotate_matrix_down(matrix):
    n = len(matrix)
    new_matrix = [[''] * n for _ in range(n)]
    for i in range(n):
        for j in range(n // 2):
            new_matrix[j][n - i - 1] = matrix[i][j]
        for j in range(n // 2, n - 1):
            new_matrix[j + 1][i] = matrix[i][j]
    return new_matrix

def rotate_matrix_up(matrix):
    n = len(matrix)
    new_matrix = [[''] * n for _ in range(n)]
    for i in range(n):
        for j in range(n // 2):
            new_matrix[n - i - 1][j] = matrix[i][j]
        for j in range(n // 2, n - 1):
            new_matrix[j - 1][i] = matrix[i][j]
    return new_matrix

def invert_rows(matrix):
    n = len(matrix)
    for i in range(n):
        matrix[i] = list(reversed(matrix[i]))

def invert_columns(matrix):
    n = len(matrix)
    for i in range(n):
        matrix[i] = list(map(lambda x: x - 1, matrix[i]))

