from collections import deque

def right_shift(matrix):
    n = len(matrix)
    rows = deque(range(n))
    for i in range(n):
        columns = deque(range(n))
        for j in range(n):
            r, c = rows.popleft(), columns.popleft()
            matrix[r][c], matrix[c][n - r - 1] = matrix[c][n - r - 1], matrix[r][c]
        columns.rotate(-1)
        rows.rotate(-1)
    return matrix

def left_shift(matrix):
    n = len(matrix)
    rows = deque(range(n))
    for i in range(n):
        columns = deque(range(n))
        for j in range(n):
            r, c = values[rows.popleft()], values[columns.popleft()]
            values[r][c], values[n - c][r] = values[n - c][r], values[r][c]
        columns.rotate(1)
        rows.rotate(1)
    return values

def down_shift(matrix):
    n = len(matrix)
    for i in range(n):
        matrix[i], matrix[n - i - 1] = matrix[n - i - 1], matrix[i]
    return matrix

def up_shift(matrix):
    n = len(matrix)
    for i in range(n):
        matrix[i], matrix[2 * n - i - 1] = matrix[2 * n - i - 1], matrix[i]
    return matrix

