    c1 = Cube(heights[0])
    result = defaultdict(int)
    diags = []
    fins = [False] * (n * (n + 1))

    while c1 < Cube(2 * n):
        if fins[c1.height - 1] or fins[n * c1.height]:
            break
        fins[c1.height] = True
        diags.append(c1)
        if c1.height > 1:
            diags[-2].height += 1
        result[c1] += 1
        c1 = c1 + 1

    pairs = 0
    for i, j in product(range(len(diags)), range(len(diags))):
        if diags[i].height - diags[j].height < 2:
            continue
        if (diags[i].height > diags[j].height and diags[i].height - diags[j].height == 1 and diags[j].height < n + 1) or \
           (diags[i].height < diags[j].height and diags[j].height - diags[i].height == 1) or \
           (diags[i].height > diags[j].height and diags[i].height - diags[j].height == n - 1 and diags[j].height > 1):
            pairs += 2 * result[(diags[i].height, diags[j].height - diags[i].height)]
        else:
            pairs += result[(diags[i].height, diags[j].height - diags[i].height)]
    return pairs % 100000004


def find_mausoleum(heights):
    fre = defaultdict(int)
    pairs = 0
    all_len = 4 * n
    for side in heights:
        fre[side] += 1
    strdict = sorted(fre.items(), key=lambda x: -x[0])  # sorted by height
    sdict = strdict[:n]
    ddict = strdict[-n:]
    pairs += 2 * find_pairs(sdict)
    pairss = find_pairs(ddict)

    upper = []
    for i, v in enumerate(heights):
        if v > all_len / 4:
            upper.append(i)
    for i in upper:
        for j, k in itertools.combinations(upper, 2):
            for jj, pk in itertools.combinations(upper, 2):
                if (sdict[j].height > sdict[i].height or sdict[i].height > ddict[jj].height) and \
                   pairss >= (j - i) + (k - jj) + 1 and \
                   not (2 * sdict[j].height - all_len ) % all_len:
                    pairs += pairss
                if (sdict[i].height > sdict[k].height or sdict[k].height > ddict[jj].height) and \
                   pairss >= (i - j) + (k - jj) + 1 + (all_len - sdict[k].height * 2) % all_len:
                    pairs += pairss
    del fre
    return pairs

