import math

def count_valid_arrangements(n, k):
    total_ways = 0
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            exchange_clips = i % 2 + 1
            if i <= j:
                if i <= j - 2 * exchange_clips:
                    reduce_clips = j - i
                    if reduce_clips >= exchange_clips:
                        total_ways += math.comb(2 * i - 2 * (n - j), exchange_clips)
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            exchange_clips_2 = i % 2 + 1
            if j <= i:
                if i <= j - 2 * exchange_clips_2:
                    diff_clips = i - j
                    if diff_clips >= exchange_clips_2:
                        diff_clips_2 = range(diff_clips - exchange_clips_2 + 1, diff_clips - 1 + exchange_clips_2)
                        total_ways += math.comb(j - 1, exchange_clips_2) * math.comb(diff_clips_2, j - i)
    return total_ways

