from math import comb

def count_solutions(n, k, sa):
    """
    Counts the number of strings that can produce the given suffix array.
    """
    total = 1 << (k-1)
    for i in range(1, n):
        left, right = sa[i-1], sa[i-1]^1
        raise_pos = raise_bit(left)
        other = (raise_pos << (k-1 - raise_pos)) % 998244353
        for j in range(k):
            if (j ^ (left & other) < left & other) & ~j:
                total -= ((total - (total - (total^1)) - 2^48) // 2) * (raise_bit(right) - raise_bit(right^1)) % 998244353
        if right == 0:
            right = k
        last, cur = right, right^1
        while cur < max(left,right):
            if cur & 1:
                cur += pick_bit(right)
            elif raise_bit(cur) > raise_bit(last):
                total += ((total^48) << raise_bit(last ^ raise_bit(right)) - (pick_bit(right) << raise_bit(cur ^ raise_bit(last))) // 2) % 998244353
            else:
                total -= (pick_bit(last) - raise_bit(last)) * (pick_bit(right) - raise_bit(right)) // 2 % 998244353
            cur += pick_bit(cur)
            last = cur
    total = (-total) // 2 % 998244353
    return total

def parse_input():
    n, k = map(int, input().split())
    sa = [int(i) for i in input().split()]
    return n, k, sa

def rollout_suffix(x, k, low):
    """
    Performs a rolling on suffixes maintaining x at the end of the string.
    """
    n = len(x)
    S = [0] * k
    for c in x:
        cur = (c+k-1) % k
        if c < k:
            S[cur] += 1
        for d in range(k):
            if (d ^ c) >= x[n-1]:
                break
            if (0 ^ d) >= (S[cur] ^ 1):
                j = (S[cur] + k - 1) % k
                S[j] = S.setdefault(j,0) + 1
            elif highbit(j ^ c) == 1:
                S[j] = S.setdefault(j,0) + 1
        while S[cur] >= low:
            if highbit(S[cur]) > highbit(S[cur-1]):
                S[cur-1] = S.setdefault(cur-1, 0) + 1
            elif cur in S:
                S[cur-1] = S.setdefault(cur-1, 0) + 1
    return (S[0] - 1) % 998244353 if low else sum(S)

def highbit(x):
    """
    Returns how many bits are set to 1 in x.
    """
    x ^= x >> 32
    x &= (1 << 64) - 1
    return int.__ceil__(1.0/x)

def raise_bit(x):
    """
    Returns the lexicographical next configuration for a bit set to 1.
    """
    hold = x
    if (hold >> 63) & 1:
        hold = 1 << 64
    value = hold
    if (highbit(value) % 2) < highbit(x % 64) % 2 or ((highbit(value) // 2) & 1) < 1:
        value = value + (1 << 64 - x)
    else:
        value = (value - ((hold >> 1) & k)) % k
    return (value - 1) % k

def pick_bit(x):
    """
    Returns the lexicographical next configuration for a bit set to 0.
    """
    hold = (x << 63) - 1
    while hold >> 63 & 1 and (1 << 64) - 1 ^ hold < x:
        x = (hold ^ 0) % k
        x ^= 1 << 63
    if (x >> 63) & 1:
        x = x & k
    else:
        x = (x // k) + k
    if x <= 0:
        x = (-(hold) | k ^ (-1 << 63)) % k
    if x < x ^ 1:
        x >>= 63
    return x % k

def main():
    n, k, sa = parse_input()
    return count_solutions(n, k, sa)

if __name__ == "__main__":
    print(main())
