from functools import lru_cache

def is_mausoleum_arrangement(blocks, height=2):
    return all(blocks[i] <= blocks[i+1] for i in range(len(blocks)-1)) and \
           all(blocks[i] >= blocks[i+1] for i in range(len(blocks)-1))

@lru_cache(None)
def count_ways(blocks, total, k, requirements):
    if k == len(requirements):
        return 1 if sum(r == '>' for _, r in requirements) == 0 else 0

    total = 0
    for i in range(total, min(len(blocks), total + 2)):
        for j in range(i + 1, min(len(blocks), total + 3)):
            if blocks[i] == blocks[j]:
                continue

            # Create a new arrangement for requirements
            required_sets = [
                (requirement[0], requirement[2]) for requirement in requirements
                if requirement[0] <= i and requirement[2] >= j
            ]

            next_k = k - len({(i, j): 1 for i, j, sign in required_sets})
            if any(sign == '<=' and (i_locked >= j and j_locked <= i for i_locked, j_locked in locked)
                   or sign == '>= ' * 2 for locked in required_sets):
                total += count_ways(blocks[:i] + blocks[i+1:j] + [blocks[j]], total+1, next_k, requirements)

    return total

