from collections import defaultdict

def find_order(A, S):
    # Sort weights by mass
    A.sort()
    n = len(A)

    # Create a dictionary to store the sum of all weights to the left of a weight
    prefix_sum = defaultdict(int)
    complete_weights = {weight for weight in A if weight < A[0]}

    # Initialize left and right pointers
    left, right = 0, 0

    # Iterate through each weight
    order = []
    while left < n and not complete_weights:
        if S[left] == 'R' and S[right] == 'L':
            # If the current weight has mass larger than the max in complete_weights
            if A[right] > max(A[complete_weights]):
                complete_weights |= {A[right]}
            right += 1
        else:
            left += 1

        # If we can't find a matching weight yet, add the missing one
        if not complete_weights:
            if left + 1 < n:
                order.append((A[left + 1], 'L'))  # Put a new smallest heavy weight
            else:
                order.append((A[-1], 'L'))  # Put the last heavy weight
            right = left + 1
        else:
            # Otherwise, return the weight from complete_weights that is friendly to the
            # next left move and the minimum left which is larger than or equal to current
            # left weight at the minimum index (to make sure two left moves don't happen in a row
            order.append((A[sorted(complete_weights, reverse=True)[0]], 'L'))
            complete_weights.remove(A[sorted(complete_weights, reverse=True)[0]])

    return ' '.join(map(str, order))

