def nprimes(a, b, n):
    sigma = defaultdict(int)
    for i in range(1, a+1):
        sigma[sum(nrange(i, a-1, b))**2] += 1
    return (sigma[i] for i in npr_range(n*b+ne-1, n, a))

def npr_range(start=None, stop=None, step=1):
    start = start or 0
    if start < 0:
        return npr_range(start+1, stop, step)
    if start > stop:
        yield from []
    yield start
    while True:
        if start % step != 0:
            yield start
        start += 1

