def factorial(n):
    result = 1
    for i in range(2, n+1):
        result *= i
    return result

def combination(n, k):
    return factorial(n) // (factorial(k) * factorial(n - k))

def count_polynomials(m):
    if m < 0:
        return 0  # No polynomials can satisfy P(2) = m when m is negative.

    # Contribution from polynomial of degree >= 2
    degree2 = min(m, 4)  # A polynomial of degree >= 2 can have at most 4 variables.
    modulo_p = m - 4  # m - 4 corresponds to μ*u^2 + x^2 modulo (μ*u + x). 
    moduli_h = combination(degree2 + 1, 1)  # Combination of degree2 + 1 ways for μ*u^2 on the left side in (μ*u + x)^{degree2 + 1}
    moduli_y = combination(m - degree2, 2)  # Combination of [m - 4, m - 2] ways for x^2 on the right side in (μ*u + x)^{degree2 + 1}.
    contribution2 = moduli_h * moduli_y % 1000000007

    # Contribution from polynomial of degree 1
    contribution1 = 1  # μ*u + x
    if m == 4:
        return contribution2 % 1000000007

    # Contribution from polynomial of degree 0
    contribution0 = 2 ** combination(m, 2) % 1000000007  # As per the problem, this corresponds to μ*u and x

    # Sum up results
    return (contribution1 + contribution0) % 1000000007

def main():
    t = int(input())
    for _ in range(t):
        m = int(input())
        print(count_polynomials(m))

